#include <bits/stdc++.h>
using namespace std;

int digitSum(long long x) {
    int sum = 0;
    while (x > 0) {
        sum += x % 10;
        x /= 10;
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    int digits = to_string(n).size();
    long long start = max(0LL, n - 9LL * digits);
    vector<long long> ans;

    for (long long i = start; i <= n; ++i) {
        if (i + digitSum(i) == n) {
            ans.push_back(i);
        }
    }

    cout << ans.size() << '\n';
    for (long long x : ans) {
        cout << x << '\n';
    }

    return 0;
}

